# --- NUEVO: helpers para armar una partida de 10 preguntas ---

import random

def _shuffle_options_in_place(q: dict) -> None:
    """
    Baraja las opciones sin romper la respuesta correcta.
    Asume que _export(...) devuelve cada ítem con:
      - "options": lista de strings con las opciones
      - "answer":  string con el texto de la opción correcta
    Si en tu _export usas otra clave (p.ej. "choices"), cambia abajo.
    """
    key_options = "options" if "options" in q else "choices"
    opts = q.get(key_options, [])
    ans = q.get("answer")

    # Barajar
    random.shuffle(opts)
    q[key_options] = opts

    # Si "answer" es el TEXTO correcto (lo habitual en tu pipeline), no hace falta tocarlo.
    # Si fuera un índice, aquí habría que recalcularlo.

def build_game_from_gp(gp_name: str, lang: str, rng: random.Random) -> dict:
    fn = GP_FUNCS.get(gp_name)
    if not fn:
        raise ValueError(f"GP no encontrado: {gp_name}")

    items = fn()
    exported = _export(items, lang)  # lista de dicts con question/options/answer...

    if not exported:
        raise ValueError(f"GP '{gp_name}' no tiene preguntas disponibles.")

    # Si hay >= 10, 1ª fija + 9 aleatorias (comportamiento anterior)
    if len(exported) >= 10:
        first_q = exported[0]
        rest = exported[1:]
        picked_rest = rng.sample(rest, k=9)
        game_questions = [first_q] + picked_rest
    else:
        # Si hay < 10, devuelve todas (manteniendo la primera fija)
        first_q = exported[0]
        rest = exported[1:]
        # Los “resto” se barajan para dar variedad
        rng.shuffle(rest)
        game_questions = [first_q] + rest

    # Barajar opciones en cada pregunta sin romper la correcta
    for q in game_questions:
        _shuffle_options_in_place(q)

    titles = _localize_gp_titles(gp_name)
    return {
        "gp": gp_name,
        "gp_en": titles["en"],
        "gp_es": titles["es"],
        "lang": lang,
        "count": len(game_questions),
        "questions": game_questions
    }


def build_game_random_gp(lang: str, rng: random.Random) -> dict:
    gp_name = rng.choice(list(GP_FUNCS.keys()))
    return build_game_from_gp(gp_name, lang, rng)




